get_category_page.code:
use WebCommander\Sdk\Resources\Settings\PageSettings\CategoryPage;

$response = CategoryPage::getCategoryPage($client);

$settings = $response->map['category_page'];
echo $settings['category_information']['subcategory']['per_page'], ' subcategories per page', PHP_EOL;
echo $settings['product_information']['load']['per_page'], ' products per page', PHP_EOL;

